/// Accepts a bare array, `{value: [...]}` or `{workItems: [...]}`;
/// returns an empty list for any other shape.
List<Map<String, dynamic>> unwrapAdoItems(dynamic decoded) {
  final List items;
  if (decoded is List) {
    items = decoded;
