        specified.isAbsolute ? specified : Directory('$base/${specified.path}');
    if (!resolved.existsSync()) {
      return gitRepositoryRoot(base) ?? base;
    }
    validateWithinAllowedBase(resolved.absolute.path, base);
    return resolved.path;
  }

